import{_ as s,o as n,c as e,a5 as t}from"./chunks/framework.CXroN2RO.js";const u=JSON.parse('{"title":"判断ガイド: クラスを分けるべきか","description":"","frontmatter":{"title":"判断ガイド: クラスを分けるべきか","study":{"source":"C++ Wiki","kind":"本文","status":"既存原稿","summary":"根拠: SRP、責務、凝集度 分けるシグナル: 変更履歴に別種の理由が混在/UI・保存・通信の都合がロジックに混入/テストのセットアップが巨大/「このクラスのこの辺だけ触る」という会話が頻発"}},"headers":[],"relativePath":"design/decisions/split-class.md","filePath":"design/decisions/split-class.md"}'),i={name:"design/decisions/split-class.md"};function l(r,a,o,d,p,h){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="判断ガイド-クラスを分けるべきか" tabindex="-1">判断ガイド: クラスを分けるべきか <a class="header-anchor" href="#判断ガイド-クラスを分けるべきか" aria-label="Permalink to &quot;判断ガイド: クラスを分けるべきか&quot;">​</a></h1><h2 id="判断フロー" tabindex="-1">判断フロー <a class="header-anchor" href="#判断フロー" aria-label="Permalink to &quot;判断フロー&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Q1. そのクラスの「変更理由」(誰のどんな都合で変わるか)を列挙せよ</span></span>
<span class="line"><span>    → 1つしかない ──&gt; 分けない(行数が多くても分けない)</span></span>
<span class="line"><span>    → 2つ以上ある ──&gt; Q2へ</span></span>
<span class="line"><span>Q2. その複数の理由で、実際に変更が起きているか?(履歴・直近の予定)</span></span>
<span class="line"><span>    → 起きていない(理屈上の分類だけ)──&gt; 保留(分割候補としてメモのみ)</span></span>
<span class="line"><span>    → 起きている ──&gt; Q3へ</span></span>
<span class="line"><span>Q3. 分けた後の2つは、独立して変更・テストできるか?</span></span>
<span class="line"><span>    → できる ──&gt; 分ける(1責務ずつ、段階的に)</span></span>
<span class="line"><span>    → 密結合のまま(常に両方一緒に変更される)──&gt; 分け方が間違い。境界を引き直す</span></span></code></pre></div><p>根拠: <a href="/study/design/solid/srp.html">SRP</a>、<a href="/study/design/foundations/responsibility-and-separation.html">責務</a>、<a href="/study/design/foundations/cohesion-and-coupling.html">凝集度</a></p><h2 id="判断材料" tabindex="-1">判断材料 <a class="header-anchor" href="#判断材料" aria-label="Permalink to &quot;判断材料&quot;">​</a></h2><ul><li><strong>分けるシグナル</strong>: 変更履歴に別種の理由が混在/UI・保存・通信の都合がロジックに混入/テストのセットアップが巨大/「このクラスのこの辺だけ触る」という会話が頻発</li><li><strong>分けないシグナル</strong>: 変更理由が1つ(数学ベクトル、純アルゴリズム)/一緒にしか変更されない/分けるとgetter/setterの橋だらけになる</li></ul><h2 id="例外" tabindex="-1">例外 <a class="header-anchor" href="#例外" aria-label="Permalink to &quot;例外&quot;">​</a></h2><ul><li><strong>行数だけを理由に分けない</strong>: 3000行でも変更理由が1つなら(稀だが)分割は不要。逆に200行でも理由が3つなら分ける</li><li><strong>プロトタイプ・ジャム</strong>: 分けない。捨てるコードに分割投資は無意味</li><li><strong>チーム分担の都合</strong>: 責務が1つでも「2人が同時に触ってコンフリクトする」なら物理分割(ファイル分割)の価値はある——設計上の分割とファイル分割は別の判断</li></ul><h2 id="トレードオフ" tabindex="-1">トレードオフ <a class="header-anchor" href="#トレードオフ" aria-label="Permalink to &quot;トレードオフ&quot;">​</a></h2><ul><li>得: 変更の局所化、テスト容易性、並行作業</li><li>失: クラス間の受け渡しコード、追跡の手数(1画面で読めなくなる)、<strong>分けすぎるとショットガン手術</strong>(1変更で多ファイル修正)——分割の失敗は「大きすぎ」と「細かすぎ」の両方向にある</li></ul><h2 id="実践のコツ" tabindex="-1">実践のコツ <a class="header-anchor" href="#実践のコツ" aria-label="Permalink to &quot;実践のコツ&quot;">​</a></h2><ul><li>分割は<strong>1責務ずつ・動かしたまま</strong>(<a href="/study/design/foundations/tech-debt-and-refactoring.html">リファクタリング</a>の手順: 抽出→委譲で旧API維持→呼び出し側移行→旧API削除)</li><li>最初の一手は「クラス分割」ではなく<strong>関数の抽出</strong>でよいことが多い(SRPの単位はクラスとは限らない → <a href="/study/design/solid/srp.html">SRPの自由関数の例</a>)</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>分割の判断基準が「行数」ではない理由を説明できますか。</li><li>「分け方が間違っている」ことを示すQ3のシグナルは?</li><li>設計上の分割とファイル分割が別の判断である例は?</li></ol><hr><p>前: <a href="/study/design/decisions/">カテゴリ目次</a> | 次: <a href="/study/design/decisions/create-interface.html">インターフェースを作るべきか</a></p>`,16)])])}const g=s(i,[["render",l]]);export{u as __pageData,g as default};
